import json
import os

def make_entry(idx, word, article, plural, pos, mn, ex_de, ex_mn, topic):
    disp = f"{article} {word}, {plural}" if pos == "noun" and article else word
    return {
        "id": f"b1_{idx:04d}",
        "word": word,
        "article": article,
        "plural": plural,
        "display": disp,
        "pos": pos,
        "mn": mn,
        "example_de": ex_de,
        "example_mn": ex_mn,
        "topic": topic,
        "level": "B1"
    }

